# 25/11/2026 (PCP): aplica em conciliacao\ppcp_web.py a distribuição de janeiro/2027 por semana (Carga vs Capacidade).
# Uso: python -X utf8 aplicar_janeiro_v35.py "C:\...\conciliacao\ppcp_web.py"   (faz backup .antes_janeiro_20261125)
import shutil, sys
p = sys.argv[1]
s = open(p, encoding="utf-8").read()
if "_janeiro_semanas" in s:
    sys.exit("já aplicado")
shutil.copy2(p, p + ".antes_janeiro_20261125")
def troca(a, b):
    global s
    if s.count(a) != 1:
        sys.exit("ancora nao encontrada (ou repetida): " + a[:80])
    s = s.replace(a, b)
troca('BASE_CAPACIDADE = "real"', 'BASE_CAPACIDADE = "real"\n# 25/11/2026 (PCP): retorno do recesso; o que vai para janeiro é distribuído por semana a partir deste dia.\nJANEIRO_INICIO = "2027-01-04"')
troca("""                reserva[k] += kg
            continue""", """                reserva[k] += kg
            itens_res.append({"pedido": str(r[0]), "ferramenta": str(r[7] or ""), "kg": kg, "entrega": ent,
                              "prensa": pr if pr in ("P7", "P4") else "", "pintura": pint})
            continue""")
troca('    itens, reserva = [], {"P7": 0.0, "P4": 0.0, "Pintura": 0.0}', '    itens, reserva, itens_res = [], {"P7": 0.0, "P4": 0.0, "Pintura": 0.0}, []')
troca('    rec_ext = []\n', '    janeiro = _janeiro_semanas(taxa, turnos_dia, horas_turno, fer, pint, itens, jan_ext, itens_res, ordem)\n    rec_ext = []\n')
troca('"fim_reserva": fim_seg.isoformat(),', '"fim_reserva": fim_seg.isoformat(), "janeiro": janeiro,')
troca("\ndef carga_capacidade(", '\n\ndef _janeiro_semanas(taxa, turnos_dia, horas_turno, fer, pint, itens, jan_ext, itens_res, ordem, semanas_min=4, semanas_max=8):\n    """25/11/2026 (PCP): o que não cabe em 2026 + entregas de 2027, distribuído por semana a partir de JANEIRO_INICIO,\n    com a mesma regra de 2026: dias úteis (seg-sex, sem feriados) × turnos × horas × kg/h; pintura é o gargalo e entra\n    primeiro (saldo de pintura de 2026, depois entregas de 2027 por ENTREGAPCP); a prensa só extruda de item de pintura o que\n    cabe na pintura de janeiro; o resto da prensa segue por ENTREGAPCP. Vai até a carga acabar (mín. 4, máx. 8 semanas);\n    o que não couber fica como "depois"."""\n    ini = dt.date.fromisoformat(JANEIRO_INICIO)\n    fim = ini + dt.timedelta(weeks=semanas_max) - dt.timedelta(days=1)\n    dias, d = [], ini\n    while d <= fim:\n        if d.weekday() < 5 and d.isoformat() not in fer:\n            dias.append(d)\n        d += dt.timedelta(days=1)\n    cap_dia = {k: {x: turnos_dia * horas_turno * taxa[k] for x in dias} for k in taxa}\n    uso = {k: {} for k in taxa}\n\n    def alocar(k, fila):\n        livres = [[x, cap_dia[k][x]] for x in dias]\n        i, ultimo, coube = 0, None, []\n        for kg in fila:\n            resto = kg\n            while resto > 1e-6 and i < len(livres):\n                usa = min(resto, livres[i][1])\n                resto -= usa\n                livres[i][1] -= usa\n                ultimo = livres[i][0]\n                uso[k][livres[i][0]] = uso[k].get(livres[i][0], 0.0) + usa\n                if livres[i][1] <= 1e-6:\n                    i += 1\n            coube.append(kg - resto)\n        return coube, ultimo\n    # filas de janeiro: (chave, prensa, pintura, kg, entrega)\n    fila = []\n    for x in pint:                                  # saldo de pintura de 2026 (extrusão também vai para janeiro)\n        kg = x["kg"] - x.get("kg_ano", x["kg"])\n        if kg > 0.01:\n            fila.append({"prensa": x["prensa"], "pintura": True, "kg": kg, "entrega": x["entrega"], "pedido": x["pedido"]})\n    for x in jan_ext:                               # extrusão sem capacidade em 2026\n        fila.append({"prensa": x["prensa"], "pintura": False, "kg": x["kg"], "entrega": dt.date.fromisoformat(x["entrega"]) if x["entrega"] else None, "pedido": x["pedido"]})\n    for x in itens_res:                             # entregas de 2027\n        fila.append({"prensa": x["prensa"], "pintura": x["pintura"], "kg": x["kg"], "entrega": x["entrega"], "pedido": x["pedido"]})\n    fila.sort(key=ordem)\n    pf = [x for x in fila if x["pintura"]]\n    coube_p, ult_p = alocar("Pintura", [x["kg"] for x in pf])\n    for x, c in zip(pf, coube_p):\n        x["kg_jan"] = c\n    linhas = {"Pintura": {"carga": round(sum(x["kg"] for x in pf), 2), "cabe": round(sum(coube_p), 2),\n                          "depois": round(sum(x["kg"] for x in pf) - sum(coube_p), 2), "fim_previsto": ult_p.isoformat() if ult_p else None}}\n    for k in ("P7", "P4"):\n        sel = [x for x in fila if x["prensa"] == k]\n        kgs = [x.get("kg_jan", x["kg"]) if x["pintura"] else x["kg"] for x in sel]\n        coube, ult = alocar(k, kgs)\n        linhas[k] = {"carga": round(sum(x["kg"] for x in sel), 2), "cabe": round(sum(coube), 2),\n                     "depois": round(sum(x["kg"] for x in sel) - sum(coube), 2), "fim_previsto": ult.isoformat() if ult else None}\n    # semanas: até a última com uso (mín. semanas_min)\n    ult_uso = max([max(u) for u in uso.values() if u] or [ini])\n    n = max(semanas_min, (ult_uso - ini).days // 7 + 1)\n    semanas = []\n    for w in range(min(n, semanas_max)):\n        seg = ini + dt.timedelta(weeks=w)\n        sex = seg + dt.timedelta(days=4)\n        du = [x for x in dias if seg <= x <= sex]\n        rot = "%s–%s" % (du[0].strftime("%d") if du[0].month == du[-1].month else du[0].strftime("%d/%m"), du[-1].strftime("%d/%m")) if du else seg.strftime("%d/%m")\n        semanas.append({"id": "S%02d" % seg.isocalendar()[1], "ini": seg.isoformat(), "fim": (seg + dt.timedelta(days=6)).isoformat(), "rotulo": rot,\n                        "linhas": {k: {"cap": round(sum(cap_dia[k][x] for x in du), 2), "carga": round(sum(v for x, v in uso[k].items() if seg <= x <= sex), 2),\n                                       "entrega": 0.0, "dias": len(du)} for k in taxa}})\n    # entregas por semana (vencidas e de 2026 na 1ª) e atraso acumulado\n    for x in fila:\n        ks = ([x["prensa"]] if x["prensa"] in ("P7", "P4") else []) + (["Pintura"] if x["pintura"] else [])\n        alvo = semanas[0]\n        if x["entrega"] and x["entrega"] >= ini:\n            alvo = semanas[-1]\n            for s in semanas:\n                if x["entrega"] <= dt.date.fromisoformat(s["fim"]):\n                    alvo = s\n                    break\n        for k in ks:\n            alvo["linhas"][k]["entrega"] += x["kg"]\n    for k in taxa:\n        ent_ac = prog_ac = 0.0\n        for s in semanas:\n            v = s["linhas"][k]\n            ent_ac += v["entrega"]\n            prog_ac += v["carga"]\n            v["entrega"] = round(v["entrega"], 2)\n            v["saldo"] = round(v["cap"] - v["carga"], 2)\n            v["atraso"] = round(max(0.0, ent_ac - prog_ac), 2)\n        linhas[k]["cap"] = round(sum(s["linhas"][k]["cap"] for s in semanas), 2)\n        linhas[k]["cap_dia"] = round(turnos_dia * horas_turno * taxa[k], 2)\n    return {"inicio": JANEIRO_INICIO, "semanas": semanas, "linhas": linhas,\n            "fim_horizonte": semanas[-1]["fim"] if semanas else JANEIRO_INICIO}\n' + "\ndef carga_capacidade(")
compile(s, p, "exec")
open(p, "w", encoding="utf-8").write(s)
print("OK: janeiro aplicado em", p)
